// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
